    """Send a notification to a user.

    Handles timeout, connection errors, and other request exceptions gracefully
    by returning an error dict instead of crashing.
    """
    try:
        response = requests.post(
            BASE_NOTIFY_URL,
            json={"user_id": user_id, "message": message},
            timeout=5,
        )
        response.raise_for_status()
        return response.json()
    except requests.exceptions.Timeout:
        return {"status": "error", "reason": "timeout"}
    except requests.exceptions.ConnectionError:
        return {"status": "error", "reason": "connection_error"}
    except requests.exceptions.HTTPError:
        return {"status": "error", "reason": "server_error"}
    except requests.exceptions.RequestException as e:
